1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getPlataformaConfig, updatePlataformaConfig, getRedeInfo } from '../../services/adminService';
4	import { useAuth } from '../../contexts/AuthContext';
5	import Icon from '../../components/AppIcon';
6	
7	const AdminConfiguracoes = () => {
8	  const navigate = useNavigate();
9	  const { signOut } = useAuth();
10	  const [config, setConfig] = useState(null);
11	  const [loading, setLoading] = useState(true);
12	  const [salvando, setSalvando] = useState(false);
13	  const [sucesso, setSucesso] = useState(false);
14	  const [erro, setErro] = useState(null);
15	
16	  const [form, setForm] = useState({
17	    pagbank_platform_token: '',
18	    pagbank_platform_account_id: '',
19	    pagbank_sandbox: true,
20	    cloudflare_tunnel_token: '',
21	    cloudflare_domain: '',
22	  });
23	  const [salvandoCf, setSalvandoCf] = useState(false);
24	  const [sucessoCf, setSucessoCf] = useState(false);
25	  const [erroCf, setErroCf] = useState(null);
26	  const [redeInfo, setRedeInfo] = useState(null);
27	
28	  useEffect(() => {
29	    getPlataformaConfig()
30	      .then((d) => {
31	        setConfig(d);
32	        setForm((f) => ({
33	          ...f,
34	          pagbank_platform_account_id: d.pagbank_platform_account_id ?? '',
35	          pagbank_sandbox: d.pagbank_sandbox ?? true,
36	          cloudflare_domain: d.cloudflare_domain ?? '',
37	        }));
38	      })
39	      .catch((e) => setErro(e.message))
40	      .finally(() => setLoading(false));
41	    getRedeInfo().then(setRedeInfo).catch(() => {});
42	  }, []);
43	
44	  const handleSalvar = async (e) => {
45	    e.preventDefault();
46	    setSalvando(true);
47	    setErro(null);
48	    setSucesso(false);
49	    try {
50	      const payload = {
51	        pagbank_platform_account_id: form.pagbank_platform_account_id.trim(),
52	        pagbank_sandbox: form.pagbank_sandbox,
53	      };
54	      if (form.pagbank_platform_token.trim()) {
55	        payload.pagbank_platform_token = form.pagbank_platform_token.trim();
56	      }
57	      const updated = await updatePlataformaConfig(payload);
58	      setConfig(updated);
59	      setForm((f) => ({ ...f, pagbank_platform_token: '' }));
60	      setSucesso(true);
61	      setTimeout(() => setSucesso(false), 3000);
62	    } catch (err) {
63	      setErro(err.message);
64	    } finally {
65	      setSalvando(false);
66	    }
67	  };
68	
69	  const handleSalvarCloudflare = async (e) => {
70	    e.preventDefault();
71	    setSalvandoCf(true);
72	    setErroCf(null);
73	    setSucessoCf(false);
74	    try {
75	      const payload = { cloudflare_domain: form.cloudflare_domain.trim() };
76	      if (form.cloudflare_tunnel_token.trim()) {
77	        payload.cloudflare_tunnel_token = form.cloudflare_tunnel_token.trim();
78	      }
79	      const updated = await updatePlataformaConfig(payload);
80	      setConfig(updated);
81	      setForm((f) => ({ ...f, cloudflare_tunnel_token: '' }));
82	      setSucessoCf(true);
83	      setTimeout(() => setSucessoCf(false), 3000);
84	    } catch (err) {
85	      setErroCf(err.message);
86	    } finally {
87	      setSalvandoCf(false);
88	    }
89	  };
90	
91	  const NavAdmin = () => (
92	    <nav className="flex gap-2 flex-wrap justify-end">
93	      {[
94	        { label: 'Dashboard', path: '/admin' },
95	        { label: 'Empresas', path: '/admin/empresas' },
96	        { label: 'Categorias', path: '/admin/categorias' },
97	        { label: 'Tipos',      path: '/admin/tipos-estabelecimento' },
98	        { label: 'Tags',       path: '/admin/tags' },
99	        { label: 'Comissões', path: '/admin/comissoes' },
100	        { label: 'Configurações', path: '/admin/configuracoes' },
101	      ].map((l) => (
102	        <button key={l.path} onClick={() => navigate(l.path)}
103	          className={`px-3 py-2 text-sm font-medium rounded-lg ${
104	            l.path === '/admin/configuracoes'
105	              ? 'text-white bg-orange-500'
106	              : 'text-gray-700 hover:bg-gray-100'
107	          }`}>
108	          {l.label}
109	        </button>
110	      ))}
111	      <button
112	        onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
113	        className="px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg border border-red-200"
114	      >
115	        Sair
116	      </button>
117	    </nav>
118	  );
119	
120	  return (
121	    <div className="min-h-screen bg-gray-50">
122	      <header className="bg-white border-b px-6 py-4 flex items-center justify-between">
123	        <div>
124	          <h1 className="text-xl font-bold text-gray-900">Configurações da Plataforma</h1>
125	          <p className="text-sm text-gray-500">Integração PagBank Marketplace (Split Payment)</p>
126	        </div>
127	        <NavAdmin />
128	      </header>
129	
130	      <main className="p-6 max-w-2xl mx-auto">
131	        {loading ? (
132	          <div className="flex justify-center py-12">
133	            <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin" />
134	          </div>
135	        ) : (
136	          <div className="space-y-6">
137	
138	            {/* Status */}
139	            <div className={`rounded-xl border p-4 flex items-start gap-3 ${
140	              config?.configurado ? 'bg-green-50 border-green-200' : 'bg-yellow-50 border-yellow-200'
141	            }`}>
142	              <Icon
143	                name={config?.configurado ? 'CheckCircle' : 'AlertCircle'}
144	                size={20}
145	                className={`mt-0.5 flex-shrink-0 ${config?.configurado ? 'text-green-600' : 'text-yellow-600'}`}
146	              />
147	              <div>
148	                <p className={`text-sm font-semibold ${config?.configurado ? 'text-green-800' : 'text-yellow-800'}`}>
149	                  {config?.configurado ? 'Split Payment configurado e ativo' : 'Split Payment não configurado'}
150	                </p>
151	                {config?.configurado ? (
152	                  <p className="text-xs text-green-600 mt-0.5">
153	                    Token: {config.pagbank_platform_token_masked} · Account: {config.pagbank_platform_account_id} · {config.pagbank_sandbox ? 'Sandbox' : 'Produção'}
154	                  </p>
155	                ) : (
156	                  <p className="text-xs text-yellow-700 mt-0.5">
157	                    Configure o token e account ID abaixo para ativar o repasse automático aos restaurantes.
158	                  </p>
159	                )}
160	              </div>
161	            </div>
162	
163	            {/* Explicação do fluxo */}
164	            <div className="bg-blue-50 border border-blue-100 rounded-xl p-5">
165	              <h2 className="text-sm font-bold text-blue-800 mb-3 flex items-center gap-2">
166	                <Icon name="Info" size={16} /> Como funciona o Split Payment
167	              </h2>
168	              <ol className="text-xs text-blue-700 space-y-2 list-decimal list-inside">
169	                <li>Cliente paga → dinheiro vai para a <strong>conta da plataforma</strong> (seu token abaixo)</li>
170	                <li>PagBank divide automaticamente: restaurante recebe a parte dele, você recebe a comissão</li>
171	                <li>Nenhum dinheiro transita manualmente — tudo automático no momento do pagamento</li>
172	              </ol>
173	              <div className="mt-3 text-xs text-blue-600 bg-blue-100 rounded-lg p-2">
174	                <strong>Restaurante precisa:</strong> informar o ID da conta deles em /restaurante/config → "ID da conta PagBank"
175	              </div>
176	            </div>
177	
178	            {/* Formulário */}
179	            <div className="bg-white rounded-xl border p-6">
180	              <h2 className="font-semibold text-gray-900 mb-1">Conta PagBank Marketplace</h2>
181	              <p className="text-sm text-gray-500 mb-5">
182	                Obtenha o token e account ID na sua conta PagBank tipo Marketplace/Facilitador.
183	              </p>
184	
185	              <form onSubmit={handleSalvar} className="space-y-4">
186	                {/* Token da plataforma */}
187	                <div>
188	                  <label className="block text-sm font-medium text-gray-700 mb-1">
189	                    Token da Plataforma (Marketplace)
190	                    {config?.configurado && (
191	                      <span className="text-xs text-gray-400 ml-2">(deixe vazio para manter atual)</span>
192	                    )}
193	                  </label>
194	                  <input
195	                    type="password"
196	                    value={form.pagbank_platform_token}
197	                    onChange={(e) => setForm((f) => ({ ...f, pagbank_platform_token: e.target.value }))}
198	                    placeholder={
199	                      config?.configurado
200	                        ? config.pagbank_platform_token_masked
201	                        : 'Token da conta Marketplace PagBank'
202	                    }
203	                    className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400"
204	                  />
205	                  <p className="text-xs text-gray-400 mt-1">
206	                    Usado para processar TODOS os pagamentos dos restaurantes da plataforma
207	                  </p>
208	                </div>
209	
210	                {/* Account ID da plataforma */}
211	                <div>
212	                  <label className="block text-sm font-medium text-gray-700 mb-1">
213	                    Account ID da Plataforma
214	                  </label>
215	                  <input
216	                    type="text"
217	                    value={form.pagbank_platform_account_id}
218	                    onChange={(e) => setForm((f) => ({ ...f, pagbank_platform_account_id: e.target.value }))}
219	                    placeholder="Ex: ACCT_XXXXXXXXXXXX"
220	                    className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400"
221	                  />
222	                  <p className="text-xs text-gray-400 mt-1">
223	                    Conta onde a comissão de cada venda será depositada automaticamente
224	                  </p>
225	                </div>
226	
227	                {/* Sandbox toggle */}
228	                <div className="flex items-center gap-3">
229	                  <button
230	                    type="button"
231	                    onClick={() => setForm((f) => ({ ...f, pagbank_sandbox: !f.pagbank_sandbox }))}
232	                    className={`relative w-10 h-6 rounded-full transition-colors ${
233	                      form.pagbank_sandbox ? 'bg-orange-400' : 'bg-green-500'
234	                    }`}
235	                  >
236	                    <span className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-transform ${
237	                      form.pagbank_sandbox ? 'left-1' : 'left-5'
238	                    }`} />
239	                  </button>
240	                  <div>
241	                    <p className="text-sm font-medium text-gray-700">
242	                      {form.pagbank_sandbox ? 'Sandbox (testes)' : 'Produção (cobranças reais)'}
243	                    </p>
244	                    <p className="text-xs text-gray-400">
245	                      {form.pagbank_sandbox
246	                        ? 'Pagamentos não são reais — para testes'
247	                        : 'Atenção: pagamentos reais serão processados'}
248	                    </p>
249	                  </div>
250	                </div>
251	
252	                {/* Comissão info */}
253	                <div className="bg-gray-50 border rounded-xl p-4">
254	                  <p className="text-xs font-semibold text-gray-700 mb-1">Comissão por restaurante</p>
255	                  <p className="text-xs text-gray-500">
256	                    Cada restaurante tem sua própria taxa configurada em <strong>Empresas → editar</strong>.
257	                    O campo <code className="bg-gray-100 px-1 rounded">comissao_pct</code> define o % descontado automaticamente no split.
258	                  </p>
259	                </div>
260	
261	                {erro && (
262	                  <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-600">{erro}</div>
263	                )}
264	                {sucesso && (
265	                  <div className="p-3 bg-green-50 border border-green-200 rounded-lg text-sm text-green-700">
266	                    Configuração salva!
267	                  </div>
268	                )}
269	
270	                <button
271	                  type="submit"
272	                  disabled={salvando}
273	                  className="w-full py-2.5 bg-orange-500 text-white rounded-lg font-medium text-sm hover:bg-orange-600 disabled:opacity-50"
274	                >
275	                  {salvando ? 'Salvando...' : 'Salvar configurações'}
276	                </button>
277	              </form>
278	            </div>
279	            {/* ── Acesso via Rede Local (WiFi) ──────────────────── */}
280	            <div className="bg-white rounded-xl border p-6">
281	              <h2 className="font-semibold text-gray-900 mb-1">Acesso via Rede Local (WiFi)</h2>
282	              <p className="text-sm text-gray-500 mb-4">
283	                Outros dispositivos na mesma rede (celulares, tablets, outros PCs) podem acessar o sistema pelo IP abaixo.
284	              </p>
285	              {redeInfo ? (
286	                <div className="space-y-3">
287	                  {redeInfo.ips.length === 0 ? (
288	                    <p className="text-sm text-yellow-700 bg-yellow-50 border border-yellow-200 rounded-lg p-3">
289	                      Nenhum IP de rede local detectado. Verifique se o PC está conectado ao WiFi ou rede cabeada.
290	                    </p>
291	                  ) : (
292	                    redeInfo.ips.map((ip) => (
293	                      <div key={ip} className="bg-gray-900 rounded-lg p-3 flex items-center justify-between gap-3">
294	                        <div>
295	                          <p className="text-gray-400 text-[10px] mb-0.5">Abrir no celular / outro PC (mesma rede WiFi)</p>
296	                          <p className="text-green-400 font-mono text-sm select-all">
297	                            http://{ip}:{redeInfo.porta}
298	                          </p>
299	                        </div>
300	                        <button
301	                          type="button"
302	                          onClick={() => navigator.clipboard?.writeText(`http://${ip}:${redeInfo.porta}`)}
303	                          className="text-xs text-gray-400 hover:text-white border border-gray-600 rounded px-2 py-1 flex-shrink-0"
304	                        >
305	                          Copiar
306	                        </button>
307	                      </div>
308	                    ))
309	                  )}
310	                  <p className="text-xs text-gray-400">
311	                    O celular e o PC devem estar na mesma rede WiFi. Para acesso externo (fora da rede), use o Cloudflare Tunnel abaixo.
312	                  </p>
313	                </div>
314	              ) : (
315	                <div className="flex items-center gap-2 text-sm text-gray-400">
316	                  <div className="w-4 h-4 border-2 border-gray-300 border-t-transparent rounded-full animate-spin" />
317	                  Detectando IP...
318	                </div>
319	              )}
320	            </div>
321	
322	            {/* ── Cloudflare Tunnel ───────────────────────────────── */}
323	            <div className="bg-white rounded-xl border p-6">
324	              <div className="flex items-center justify-between mb-1">
325	                <h2 className="font-semibold text-gray-900">Acesso via Cloudflare Tunnel</h2>
326	                {config?.cloudflare_configurado ? (
327	                  <span className="flex items-center gap-1.5 text-xs font-semibold text-green-700 bg-green-50 border border-green-200 px-2.5 py-1 rounded-full">
328	                    <span className="w-1.5 h-1.5 rounded-full bg-green-500" /> Ativo
329	                  </span>
330	                ) : (
331	                  <span className="flex items-center gap-1.5 text-xs font-semibold text-gray-500 bg-gray-100 border border-gray-200 px-2.5 py-1 rounded-full">
332	                    <span className="w-1.5 h-1.5 rounded-full bg-gray-400" /> Não configurado
333	                  </span>
334	                )}
335	              </div>
336	              <p className="text-sm text-gray-500 mb-5">
337	                Permite que clientes externos acessem o sistema via domínio público seguro (HTTPS), mesmo sem IP fixo ou servidor.
338	              </p>
339	
340	              {/* Passo a passo de configuração */}
341	              <div className="bg-blue-50 border border-blue-100 rounded-xl p-5 mb-5 space-y-4">
342	                <h3 className="text-sm font-bold text-blue-800 flex items-center gap-2">
343	                  <Icon name="Info" size={15} /> Como configurar (faça uma vez)
344	                </h3>
345	                <ol className="space-y-3 text-xs text-blue-800">
346	                  <li className="flex gap-3">
347	                    <span className="w-5 h-5 rounded-full bg-blue-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">1</span>
348	                    <div>
349	                      <p className="font-semibold">Crie uma conta Cloudflare (gratuito)</p>
350	                      <p className="text-blue-600 mt-0.5">Acesse <strong>one.dash.cloudflare.com</strong> e crie ou entre na sua conta</p>
351	                    </div>
352	                  </li>
353	                  <li className="flex gap-3">
354	                    <span className="w-5 h-5 rounded-full bg-blue-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">2</span>
355	                    <div>
356	                      <p className="font-semibold">Crie o Tunnel</p>
357	                      <p className="text-blue-600 mt-0.5">No painel Cloudflare: <strong>Zero Trust → Networks → Tunnels → Create a tunnel</strong></p>
358	                      <p className="text-blue-600">Escolha "Cloudflared" → dê um nome → clique em Next</p>
359	                    </div>
360	                  </li>
361	                  <li className="flex gap-3">
362	                    <span className="w-5 h-5 rounded-full bg-blue-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">3</span>
363	                    <div>
364	                      <p className="font-semibold">Copie o token</p>
365	                      <p className="text-blue-600 mt-0.5">Na tela de instalação, copie o token longo que aparece após <code className="bg-blue-100 px-1 rounded">--token</code></p>
366	                      <p className="text-blue-600">Cole no campo abaixo e salve</p>
367	                    </div>
368	                  </li>
369	                  <li className="flex gap-3">
370	                    <span className="w-5 h-5 rounded-full bg-blue-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">4</span>
371	                    <div>
372	                      <p className="font-semibold">Configure o domínio público no Tunnel</p>
373	                      <p className="text-blue-600 mt-0.5">Em "Public Hostname": subdomínio → seu domínio → Service: <code className="bg-blue-100 px-1 rounded">HTTP · localhost:4028</code></p>
374	                      <p className="text-blue-600">Coloque o mesmo domínio no campo abaixo</p>
375	                    </div>
376	                  </li>
377	                  <li className="flex gap-3">
378	                    <span className="w-5 h-5 rounded-full bg-blue-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">5</span>
379	                    <div>
380	                      <p className="font-semibold">Instale e rode o cloudflared no PC</p>
381	                      <div className="bg-gray-900 rounded-lg p-2 mt-1 space-y-1 font-mono">
382	                        <p className="text-gray-400 text-[10px]"># instalar (só 1x, Windows)</p>
383	                        <p className="text-green-400 text-[10px] select-all">winget install Cloudflare.cloudflared</p>
384	                        <p className="text-gray-400 text-[10px] mt-1"># rodar sempre que ligar o PC</p>
385	                        <p className="text-yellow-300 text-[10px] break-all select-all">
386	                          cloudflared tunnel run --token{' '}
387	                          <span className="text-white">{config?.cloudflare_tunnel_token_masked ?? '<COLE O TOKEN AQUI>'}</span>
388	                        </p>
389	                      </div>
390	                    </div>
391	                  </li>
392	                  {config?.cloudflare_domain && (
393	                    <li className="flex gap-3">
394	                      <span className="w-5 h-5 rounded-full bg-green-600 text-white font-bold flex items-center justify-center flex-shrink-0 text-[10px]">✓</span>
395	                      <div>
396	                        <p className="font-semibold text-green-800">Acesse via domínio público</p>
397	                        <a
398	                          href={`https://${config.cloudflare_domain}`}
399	                          target="_blank"
400	                          rel="noopener noreferrer"
401	                          className="text-blue-600 underline font-mono text-[11px]"
402	                        >
403	                          https://{config.cloudflare_domain}
404	                        </a>
405	                      </div>
406	                    </li>
407	                  )}
408	                </ol>
409	              </div>
410	
411	              <form onSubmit={handleSalvarCloudflare} className="space-y-4">
412	                <div>
413	                  <label className="block text-sm font-medium text-gray-700 mb-1">
414	                    Token do Tunnel
415	                    {config?.cloudflare_configurado && (
416	                      <span className="text-xs text-gray-400 ml-2">(deixe vazio para manter atual: {config.cloudflare_tunnel_token_masked})</span>
417	                    )}
418	                  </label>
419	                  <input
420	                    type="password"
421	                    value={form.cloudflare_tunnel_token}
422	                    onChange={(e) => setForm((f) => ({ ...f, cloudflare_tunnel_token: e.target.value }))}
423	                    placeholder="eyJhIjoiXXX... (obtido no Cloudflare Zero Trust)"
424	                    className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400"
425	                  />
426	                  <p className="text-xs text-gray-400 mt-1">
427	                    Cloudflare Zero Trust → Tunnels → criar tunnel → copiar token
428	                  </p>
429	                </div>
430	
431	                <div>
432	                  <label className="block text-sm font-medium text-gray-700 mb-1">Domínio público</label>
433	                  <input
434	                    type="text"
435	                    value={form.cloudflare_domain}
436	                    onChange={(e) => setForm((f) => ({ ...f, cloudflare_domain: e.target.value }))}
437	                    placeholder="delivery.seudominio.com"
438	                    className="w-full border rounded-lg px-3 py-2 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-orange-400"
439	                  />
440	                  <p className="text-xs text-gray-400 mt-1">
441	                    Apenas letras, números, pontos e hífens. Ex: pedidos.seusite.com.br
442	                  </p>
443	                </div>
444	
445	                {erroCf && (
446	                  <div className="p-3 bg-red-50 border border-red-200 rounded-lg text-sm text-red-600">{erroCf}</div>
447	                )}
448	                {sucessoCf && (
449	                  <div className="p-3 bg-green-50 border border-green-200 rounded-lg text-sm text-green-700">
450	                    Configuração Cloudflare salva!
451	                  </div>
452	                )}
453	
454	                <button
455	                  type="submit"
456	                  disabled={salvandoCf}
457	                  className="w-full py-2.5 bg-orange-500 text-white rounded-lg font-medium text-sm hover:bg-orange-600 disabled:opacity-50"
458	                >
459	                  {salvandoCf ? 'Salvando...' : 'Salvar configuração Cloudflare'}
460	                </button>
461	              </form>
462	            </div>
463	
464	          </div>
465	        )}
466	      </main>
467	    </div>
468	  );
469	};
470	
471	export default AdminConfiguracoes;
