    <button
      onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
      className="px-3 py-2 text-sm font-medium text-red-600 hover:bg-red-50 rounded-lg border border-red-200"
    >
      Sair
    </button>
  </nav>
);

